         aspect.num = frame->sample_aspect_ratio.num;
         aspect.den = frame->sample_aspect_ratio.den;
     }
     if (aspect.den) {
         urational_simplify(&aspect);
         uref_pic_set_aspect(uref, aspect);
     }

